contract InvMutTest {
    C c;

    constructor() { c = new C(); }
    function __ESBMC_reverted() internal returns (bool) {}
    function __ESBMC_assume(bool) internal pure {}

    function run(uint _val) public payable {
        uint beforeMinSum = c.MinSum(); if (__ESBMC_reverted()) return;
        uint afterMinSum;
        bool reverted;
        c.SetMinSum(_val); bool __rev0 = __ESBMC_reverted(); if (__rev0) {
            reverted = true;
            afterMinSum = c.MinSum();
        } else {
            reverted = false;
            afterMinSum = c.MinSum();
        }
        assert(reverted ? afterMinSum == beforeMinSum : afterMinSum == _val);
    }

    receive() external payable {}
}

