// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;

import {Test} from "forge-std/Test.sol";
import {DEP_BANK} from "../src/DEP_BANK.sol";

contract InvMutTest is Test {
    uint256 internal constant VALUE_CAP = 1000000000000000000000000000000;
    DEP_BANK c;

    function setUp() public {
        c = new DEP_BANK();
    }

    function _run(uint256 _val) internal {
        uint256 beforeMinSum;
        try c.MinSum() returns (uint256 __r) { beforeMinSum = __r; } catch { return; }
        uint afterMinSum;
        bool reverted;
        try c.SetMinSum(_val) {
            reverted = false;
            afterMinSum = c.MinSum();
        } catch {
            reverted = true;
            afterMinSum = c.MinSum();
        }
        assertTrue(reverted ? afterMinSum == beforeMinSum : afterMinSum == _val);
    }

    function testFuzz_run(uint256 _val) public {
        _run(_val);
    }

    receive() external payable {}
}
